<template>
  <div class="auth-page"><div class="auth-toolbar"><PreferenceControls /></div><div class="auth-layout"><section class="auth-intro"><div class="auth-brand"><span class="brand-mark"><Sparkles :size="17" /></span><span>{{ t('common.brand') }}</span></div><p class="eyebrow">{{ t('auth.eyebrow') }}</p><h1>{{ t('auth.title') }}</h1><p>{{ t('auth.subtitle') }}</p><div class="intro-rule"></div></section><section class="auth-card card"><p class="eyebrow">{{ t('common.product') }}</p><h2>{{ t('common.login') }}</h2><form @submit.prevent="handleLogin"><div class="form-group"><label>{{ t('common.email') }}</label><input v-model="email" type="email" :placeholder="t('auth.placeholderEmail')" required /></div><div class="form-group"><label>{{ t('common.password') }}</label><input v-model="password" type="password" :placeholder="t('auth.placeholderPassword')" required /></div><p v-if="error" class="error form-message">{{ error }}</p><button class="btn-primary auth-submit" type="submit" :disabled="loading">{{ loading ? t('common.loggingIn') : t('common.login') }}<ArrowUpRight :size="16" /></button></form></section></div></div>
</template>
<script setup>
import { ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { ArrowUpRight, Sparkles } from '@lucide/vue'; import { useAuthStore } from '../stores/auth'; import { authApi } from '../api'; import PreferenceControls from '../components/PreferenceControls.vue'
const { t } = useI18n(); const router = useRouter(); const authStore = useAuthStore(); const email = ref('admin@jianshi-ai.local'); const password = ref(''); const error = ref(''); const loading = ref(false)
async function handleLogin() { error.value = ''; loading.value = true; try { const data = await authApi.login(email.value, password.value); authStore.setAuth({ ...data, email: email.value }); router.push('/') } catch (e) { error.value = e.message } finally { loading.value = false } }
</script>
