.auth-page { min-height:100vh; padding:28px 40px; display:grid; place-items:center; } .auth-toolbar { position:fixed; top:24px; right:40px; } .auth-layout { width:min(100%,850px); display:grid; grid-template-columns:1fr 390px; gap:76px; align-items:center; } .auth-intro { padding:24px 0; } .auth-brand { display:inline-flex; align-items:center; gap:10px; margin-bottom:74px; font-size:18px; font-weight:750; } .brand-mark { width:32px; height:32px; display:grid; place-items:center; border-radius:9px; color:var(--primary-text); background:var(--primary); } .auth-intro h1 { margin-top:17px; font-size:clamp(38px,6vw,58px); font-weight:650; } .auth-intro > p:not(.eyebrow) { max-width:300px; margin-top:20px; color:var(--text-soft); line-height:1.7; } .intro-rule { width:80px; height:1px; margin-top:78px; background:var(--border-strong); } .auth-card { padding:34px; } .auth-card h2 { margin:8px 0 28px; font-size:26px; font-weight:650; } .auth-submit { width:100%; margin-top:4px; } .form-message { margin:-4px 0 14px; }
@media(max-width:720px) { .auth-page { padding:84px 16px 28px; } .auth-toolbar { top:20px; right:16px; } .auth-layout { display:block; } .auth-intro { padding:0 8px 28px; } .auth-brand { margin-bottom:42px; } .auth-intro h1 { font-size:42px; } .intro-rule { margin-top:32px; } .auth-card { padding:24px 20px; } }
</style>
